#pragma once
// AI: below section was generated by an AI
//
// The clock a board runs from another board's beat, received in the MoonModules sync format.
// https://moonmodules.org/MoonLight/reference/audio-sync.html
//
// Packets arrive with the network's jitter, so a packet does not set the clock: the clock runs on
// at the received tempo and packets pull it. A packet at a tempo more than 4% away sets it outright.
//
// A packet can be late but never early, so the least late ones say where the beat is. An access
// point holds multicast for its sleeping stations and releases it in bunches (every 100 ms is
// usual, with stalls of several hundred), so most packets are stale; pulling a quarter of the way
// to each one, as the specification says, settles at their average age. Instead a packet ahead of
// the clock pulls it at once, and the others pull it only by the least late of a window of
// WINDOW_MS, which is longer than the packets are held.
//
// A packet's place in the bar and the phrase say by how many whole beats it is late: at 120 BPM
// a packet held for 300 ms would otherwise look 200 ms early. Where neither is known, that is
// the limit.
//
// A sender whose numbering moved is late or early by whole beats in every packet. So when nothing
// in a whole window was within half a beat, the clock is set to the sender's numbering.
//
// No platform calls and no locking: the caller passes the time and guards the object.

#include <stdint.h>
#include <math.h>

struct ArNetBeatPacket {
  float    bpm;           // beats per minute
  float    phase;         // 0..1 through the beat
  uint16_t beatCount;     // the sender's count, wrapping
  uint8_t  beatInBar;     // 1..4, 0 = unknown
  uint8_t  beatInPhrase;  // 1..phraseBeats, 0 = unknown
  uint8_t  phraseBeats;   // the phrase's length, 0 = none
  bool     downbeatKnown; // beatInBar is measured or marked
  bool     fill;          // the beat is in a fill
};

struct ArNetBeatNow {
  float    bpm;
  float    progress;      // 0..1 through the beat
  uint32_t beatsElapsed;  // the sender's count, run on
  uint8_t  beatInBar;     // 1..4, always
  uint8_t  beatInPhrase;  // 1..phraseBeats, 0 = no phrase
  uint8_t  phraseBeats;
  bool     downbeatKnown;
  bool     fill;
  uint32_t gen;           // changes when the numbering moved
};

class ArNetBeatClock {
  public:
    static constexpr float    PULL          = 0.5f;   // how far a packet that counts pulls the clock to its phase
    static constexpr uint32_t WINDOW_MS     = 500;    // the window the least late packet is taken from
    static constexpr float    TEMPO_RESET   = 0.04f;  // a tempo this far away sets the clock outright
    static constexpr float    BPM_MIN       = 20.0f;  // slower than this is not a beat to follow
    static constexpr uint32_t STALE_BEATS   = 4;      // the beat ends this long after the last packet

    // Forget the beat: the next packet starts the clock again.
    void reset() { _live = false; }

    // A packet that arrived at atMs and is taken at nowMs: the loop gets to it some time later.
    void packet(const ArNetBeatPacket& p, uint32_t atMs, uint32_t nowMs) {
      if (!(p.bpm >= BPM_MIN)) return;
      if (_live && (int32_t)(atMs - _atMs) < 0) atMs = _atMs;   // never before the last one
      if (!_live || stale(atMs)) { start(p, atMs); return; }

      const double shown     = positionAt(nowMs);      // where the beat is on show
      const double predicted = positionAt(atMs);
      const double err       = errorOf(p, predicted);
      if (phraseLen(p) == _phraseLen) _lenSame = true;

      double pos = predicted;
      bool   agrees = err > -0.5;
      if (fabsf(p.bpm - _bpm) > _bpm * TEMPO_RESET) {
        _owed = 0.0;
        if (agrees) {
          pos = predicted + err;
        } else {
          pos = setOutright(p, predicted);
        }
        restartWindow(atMs);
      } else if (err > 0.0) {
        _owed = 0.0;
        pos = predicted + PULL * err;
        restartWindow(atMs);
      } else if (_owed < 0.0) {
        pos = predicted + _owed;      // the rest of a correction that was held at a beat
        restartWindow(atMs);          // what comes before it is done would be counted twice
      } else {
        if (err > _leastLate) _leastLate = err;
        if (atMs - _windowMs >= WINDOW_MS) {
          if (_leastLate > -0.5 && _lenSame) {
            _owed = PULL * _leastLate;
            pos = predicted + _owed;
          } else {
            pos = setOutright(p, predicted);
            agrees = false;           // the labels are taken already
          }
          restartWindow(atMs);
        }
      }
      // Never back over a beat that has been shown: it would be a beat twice. The clock waits at
      // the beat instead, and the rest of the correction is owed.
      const double wanted = pos;
      const double next = pos + (double)(uint32_t)(nowMs - atMs) * p.bpm / 60000.0;
      if (floor(next) < floor(shown)) pos += floor(shown) - next;
      _owed = wanted - pos;
      if (_owed > -0.001) _owed = 0.0;

      _pos  = pos;
      _atMs = atMs;
      _bpm  = p.bpm;
      if (agrees && phraseLen(p) == _phraseLen) {
        const int64_t beat  = (int64_t)floor(predicted + err - p.phase + 0.5);   // the clock's beat that the packet names
        const int64_t moved = beat - _labelBeat;
        _bar    = (uint8_t)wrap(_bar + moved, 4);
        _phrase = _phraseLen ? (uint8_t)wrap(_phrase + moved, _phraseLen) : 0;
        _count  = p.beatCount;
        _labelBeat = beat;
        _fill   = p.fill;
        _downbeatKnown = p.downbeatKnown;
      }
    }

    // Where the beat is now. False when there is none.
    bool now(uint32_t nowMs, ArNetBeatNow& out) const {
      if (!_live || stale(nowMs)) return false;
      const double  pos   = positionAt(nowMs);
      const int64_t beat  = (int64_t)floor(pos);
      const int64_t moved = beat - _labelBeat;
      out.bpm           = _bpm;
      out.progress      = (float)(pos - (double)beat);
      out.beatsElapsed  = (uint32_t)((int64_t)_count + moved);
      out.beatInBar     = (uint8_t)wrap(_bar + moved, 4) + 1;
      out.phraseBeats   = _phraseLen;
      out.beatInPhrase  = _phraseLen ? (uint8_t)(wrap(_phrase + moved, _phraseLen) + 1) : 0;
      out.downbeatKnown = _downbeatKnown;
      out.fill          = _fill;
      out.gen           = _gen;
      return true;
    }

  private:
    bool     _live = false;
    double   _pos = 0.0;          // the position in beats at _atMs
    uint32_t _atMs = 0;
    float    _bpm = 0.0f;
    double   _leastLate = -1e9;   // the least late packet of the window, in beats (0 = on time)
    uint32_t _windowMs = 0;       // when the window began
    double   _owed = 0.0;         // a correction held at a beat and still to be made, in beats (0 or below)
    bool     _downbeatKnown = false;
    bool     _fill = false;
    // The labels: beat _labelBeat of this clock is place _bar of its bar and _phrase of its phrase.
    int64_t  _labelBeat = 0;
    uint8_t  _bar = 0;            // 0..3
    uint8_t  _phrase = 0;         // 0.._phraseLen-1
    uint8_t  _phraseLen = 0;
    uint32_t _count = 0;          // the sender's count at _labelBeat
    bool     _lenSame = false;    // a packet of the window had the phrase length of the labels
    uint32_t _gen = 0;

    static int64_t wrap(int64_t v, int64_t n) { const int64_t r = v % n; return r < 0 ? r + n : r; }

    double positionAt(uint32_t nowMs) const { return _pos + (double)(uint32_t)(nowMs - _atMs) * _bpm / 60000.0; }

    bool stale(uint32_t nowMs) const { return (float)(uint32_t)(nowMs - _atMs) * _bpm > STALE_BEATS * 60000.0f; }

    void restartWindow(uint32_t atMs) { _leastLate = -1e9; _windowMs = atMs; _lenSame = false; }

    static bool barOf(const ArNetBeatPacket& p) { return p.beatInBar >= 1 && p.beatInBar <= 4; }

    // The packet's error from the clock within the beat alone, the short way round.
    static double shortError(const ArNetBeatPacket& p, double predicted) {
      double e = (double)p.phase - (predicted - floor(predicted));
      if (e > 0.5) e -= 1.0;
      if (e < -0.5) e += 1.0;
      return e;
    }

    // The packet's error from the clock in beats: above 0 it is early, at most 0.5; below, late.
    // Labels that contradict each other are as late as can be, so they count for nothing.
    double errorOf(const ArNetBeatPacket& p, double predicted) const {
      const int64_t beat  = (int64_t)floor(predicted);
      const double  frac  = predicted - (double)beat;
      const int64_t moved = beat - _labelBeat;
      const uint8_t len   = phraseLen(p);
      int period = 1;
      double e = (double)p.phase - frac;
      double early = 0.25;                       // no labels: lateness of up to 0.75 can be told
      if (len && len == _phraseLen) {
        period = len;
        e += (double)(p.beatInPhrase - 1) - (double)wrap(_phrase + moved, len);
        early = 0.5;
      } else if (barOf(p)) {
        period = 4;
        e += (double)(p.beatInBar - 1) - (double)wrap(_bar + moved, 4);
        early = 0.5;
      }
      while (e > early) e -= period;
      while (e <= early - period) e += period;
      if (period > 4 && barOf(p)) {              // the bar must say the same beat
        const int64_t named = (int64_t)floor(predicted + e - p.phase + 0.5);
        if (wrap(_bar + named - _labelBeat, 4) != p.beatInBar - 1) return -1e9;
      }
      return e;
    }

    static uint8_t phraseLen(const ArNetBeatPacket& p) {
      return (p.beatInPhrase >= 1 && p.beatInPhrase <= p.phraseBeats) ? p.phraseBeats : 0;
    }

    void start(const ArNetBeatPacket& p, uint32_t atMs) {
      _live = true;
      _pos  = p.phase;
      _atMs = atMs;
      _bpm  = p.bpm;
      restartWindow(atMs);
      _labelBeat = 0;
      _owed = 0.0;
      takeLabels(p, 0);
    }

    // Set the clock to the packet's phase and numbering; returns the position.
    double setOutright(const ArNetBeatPacket& p, double predicted) {
      const double pos = predicted + shortError(p, predicted);
      takeLabels(p, (int64_t)floor(pos - p.phase + 0.5));
      return pos;
    }

    void takeLabels(const ArNetBeatPacket& p, int64_t beat) {
      // A place in the bar that is unknown is counted from the first beat heard.
      _bar       = (p.beatInBar >= 1 && p.beatInBar <= 4) ? (uint8_t)(p.beatInBar - 1) : (uint8_t)wrap(_bar + beat - _labelBeat, 4);
      _phraseLen = phraseLen(p);
      _phrase    = _phraseLen ? (uint8_t)(p.beatInPhrase - 1) : 0;
      _count     = p.beatCount;
      _labelBeat = beat;
      _fill      = p.fill;
      _downbeatKnown = p.downbeatKnown;
      _gen++;
    }
};
// AI: end
